;;
; @file   script_2D.asm
; @brief   Looping decorative actor (sprite table L083) that moves along a fixed square path forever while the player
;         keeps control. No direct AIExecute caller was found (?); purpose not established.
; @bank   $B4   (AI byte code; script id $2D, slot table generated by tools/ai/aidata.py from defs/ai/scripts.json)
; @see    docs/ai/commands.md
;;



    incsrc "../../../../build/gen/ai/slots_2D.asm"
 
; Slot 0.
; Entry code: starts 1 child script (slots $01).
; Slot index: 0
pAIScripting0x2D_Data01:
    %AICMD0x07_SetPlayerDirection(!PDIR_UP)                    ;B4C5A4
    %AICMD0x09_StartScript($01, pAIScripting0x2D_Data01_Actor01)                                   ;B4C5A6
    %AICMD0x11_EnableUserControl()                             ;B4C5AA
    %AICMD0x38_WaitForFadeIn()                                               ;B4C5AB
; Idle loop: wait one frame at a time.
pAIScripting0x2D_Data01_Idle:
    %AICMD0x13_Wait(1)                                         ;B4C5AC
    %AICMD0x12_Jump(pAIScripting0x2D_Data01_Idle)                                   ;B4C5AF
; Child script (slot $01) of Data01: actor. Spawns at (264,26).
pAIScripting0x2D_Data01_Actor01:
    %AICMD0x1A_SpawnNpc($0108, $001A, aAIScriptingData_L083, $00)                     ;B4C5B2
pAIScripting0x2D_L003:
    %AICMD0x0D_MoveObject($01, $00, $08, $01)                             ;B4C5BA
    %AICMD0x0D_MoveObject($00, $FF, $06, $01)                             ;B4C5BF
    %AICMD0x0D_MoveObject($FF, $00, $08, $02)                             ;B4C5C4
    %AICMD0x0D_MoveObject($FF, $01, $04, $01)                             ;B4C5C9
    %AICMD0x0D_MoveObject($01, $00, $0C, $02)                             ;B4C5CE
    %AICMD0x0D_MoveObject($FF, $00, $06, $01)                             ;B4C5D3
    %AICMD0x0D_MoveObject($00, $FF, $10, $02)                             ;B4C5D8
    %AICMD0x0D_MoveObject($FF, $01, $04, $01)                             ;B4C5DD
    %AICMD0x0D_MoveObject($01, $01, $0C, $02)                             ;B4C5E2
    %AICMD0x0D_MoveObject($01, $00, $08, $02)                             ;B4C5E7
    %AICMD0x0D_MoveObject($00, $FF, $06, $01)                             ;B4C5EC
    %AICMD0x12_Jump(pAIScripting0x2D_L003)                                   ;B4C5F1
